<article class="gamification-detail"><header><span class="gamification-badge"><?php echo utf8_htmlentities($tournament['status']) ?></span><h1><?php echo utf8_htmlentities($tournament['title']) ?></h1><p><?php echo utf8_htmlentities($tournament['starts_at'] ?? '') ?><?php if ($tournament['location']): ?> · <?php echo utf8_htmlentities($tournament['location']) ?><?php endif ?></p></header><div class="gamification-copy"><?php echo nl2br(utf8_htmlentities($tournament['description'])) ?></div><h2><?php echo $this->lang('Participants') ?></h2><ol class="gamification-roster"><?php foreach ($participants as $row): ?><li><strong><?php echo utf8_htmlentities($row['team_title'] ?: $row['name']) ?></strong><?php if ($row['group_name']): ?> <span><?php echo $this->lang('Group %s', utf8_htmlentities($row['group_name'])) ?></span><?php endif ?></li><?php endforeach ?></ol></article>
